import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid or empty webpage URL provided.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Error accessing the webpage: {e}") from e
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0
        headers = [header.text_content().strip() for header in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = [col.text_content().strip() for col in row.xpath('.//td')]
            if cols:
                data.append(cols)
        if not data:
            return 0
        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error processing HTML content: {e}") from e
    try:
        conn = sqlite3.connect(database_name)
        cursor = conn.cursor()
        cursor.execute("DROP TABLE IF EXISTS my_table")
        columns = ', '.join([f'"{col}" TEXT' for col in df.columns])
        cursor.execute(f"CREATE TABLE my_table ({columns})")
        for _, row in df.iterrows():
            cursor.execute(f"INSERT INTO my_table VALUES ({', '.join(['?' for _ in range(len(row))])})", tuple(row))
        conn.commit()
        row_count = cursor.execute("SELECT COUNT(*) FROM my_table").fetchone()[0]
        conn.close()
        return row_count
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}") from e

