import requests
def task_func(api_url, template_folder):
    if not api_url or not template_folder:
        raise ValueError("Both 'api_url' and 'template_folder' must be non-empty strings.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPIResource, '/api/data')

    return app

